<main class="section narrow"><span class="eyebrow">Postfach</span><h1>Benachrichtigungen</h1><div class="worklist"><?php foreach($notifications as $n):?><div class="work-row"><div><b><?=App\Core\View::e($n['title'])?></b><span><?=App\Core\View::e($n['message'])?><br><?=date('d.m.Y H:i',strtotime($n['created_at']))?></span></div><?php if($n['url']):?><a href="<?=App\Core\View::e($n['url'])?>">Öffnen</a><?php endif;?></div><?php endforeach;?><?php if(!$notifications):?><div class="empty">Keine Benachrichtigungen.</div><?php endif;?></div></main>